    if not text:
        return 0

    left, right, max_length = 0, 0, 0
    char_set = set()

    while right < len(text):
        if text[right] in char_set:
            while text[left] != text[right]:
                char_set.remove(text[left])
                left += 1
            left += 1
        else:
            char_set.add(text[right])
            right += 1
        max_length = max(max_length, right - left)

