def solve(data):
    text = data["text"]
    if not text:
        return 0

    max_length = 0
    current_length = 0
    char_index_map = {}

    for i, char in enumerate(text):
        if char in char_index_map:
            current_length = i - char_index_map[char]
            char_index_map[char] = i
        else:
            char_index_map[char] = i
            current_length += 1

        max_length = max(max_length, current_length)

    return max_length

